export default function MenuCard({ item, quantity, addToCart, removeFromCart }) {
  const isTopRated = item.avg_rating >= 4.5;
  const isPopular = item.sold >= 10;

  const outOfStock = item.stock === 0;

  return (
    <div className="menu-card">
      <div className="menu-badges">
        {isPopular && <span className="badge popular">🔥 Popular</span>}
        {isTopRated && <span className="badge rated">⭐ Top Rated</span>}
      </div>

      <h3>{item.name}</h3>

      <p className="price">₹{item.price}</p>

      <p className="rating">
        ⭐ {item.avg_rating || 0} | Sold: {item.sold || 0}
      </p>

      <p className={`stock ${outOfStock ? "out" : ""}`}>
        {outOfStock ? "Out of Stock" : `Stock: ${item.stock}`}
      </p>

      {/* ADD / COUNTER CONTROLS */}
      {quantity === 0 ? (
        <button
          disabled={outOfStock}
          className="add-btn"
          onClick={() => addToCart(item)}
        >
          {outOfStock ? "Unavailable" : "ADD"}
        </button>
      ) : (
        <div className="qty-control">
          <button
            className="qty-btn"
            onClick={() => removeFromCart(item.id)}
          >
            −
          </button>

          <span className="qty-value">{quantity}</span>

          <button
            className="qty-btn"
            onClick={() => addToCart(item)}
            disabled={outOfStock || quantity >= item.stock}
          >
            +
          </button>
        </div>
      )}
    </div>
  );
}
